python
def squareGaugesPeakTicket(readings, k):
    a=readings
    out=[]
    for x in a:
        left,right=0,x+1
        while left+1<right:
            mid=(left+right)//2
            if mid*mid<=x: left=mid
            else: right=mid
        out.append(left)
    return max(out,default=0)


java
class Solution {
  public int squareGaugesPeakTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){int l=0,r=x+1;while(l+1<r){int m=l+(r-l)/2;if((long)m*m<=x)l=m;else r=m;}out.add(l);}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
